27	/**
28	 * Maps from TensorFlow operations to Vespa operations.
29	 *
30	 * @author bratseth
31	 * @author lesters
32	 */
33	public class OperationMapper {
34	
35	    public static TensorFlowOperation get(NodeDef node, List<TensorFlowOperation> inputs, int port) {
36	        switch (node.getOp().toLowerCase()) {
37	            // array ops
38	            case "const":       return new Const(node, inputs, port);
39	            case "expanddims":  return new ExpandDims(node, inputs, port);
40	            case "identity":    return new Identity(node, inputs, port);
41	            case "placeholder": return new Placeholder(node, inputs, port);
42	            case "placeholderwithdefault": return new PlaceholderWithDefault(node, inputs, port);
43	            case "reshape":     return new Reshape(node, inputs, port);
44	            case "shape":       return new Shape(node, inputs, port);
45	            case "squeeze":     return new Squeeze(node, inputs, port);
46	
47	            // control flow
48	            case "merge":       return new Merge(node, inputs, port);
49	            case "switch":      return new Switch(node, inputs, port);
50	
51	            // math ops
52	            case "add":         return new Join(node, inputs, port, ScalarFunctions.add());
53	            case "add_n":       return new Join(node, inputs, port, ScalarFunctions.add());
54	            case "acos":        return new Map(node, inputs, port, ScalarFunctions.acos());
55	            case "div":         return new Join(node, inputs, port, ScalarFunctions.divide());
56	            case "realdiv":     return new Join(node, inputs, port, ScalarFunctions.divide());
57	            case "floor":       return new Map(node, inputs, port, ScalarFunctions.floor());
58	            case "matmul":      return new Matmul(node, inputs, port);
59	            case "maximum":     return new Join(node, inputs, port, ScalarFunctions.max());
60	            case "mean":        return new Mean(node, inputs, port);
61	            case "reducemean":  return new Mean(node, inputs, port);
62	            case "mul":         return new Join(node, inputs, port, ScalarFunctions.multiply());
63	            case "multiply":    return new Join(node, inputs, port, ScalarFunctions.multiply());
64	            case "rsqrt":       return new Map(node, inputs, port, ScalarFunctions.rsqrt());
65	            case "select":      return new Select(node, inputs, port);
66	            case "where3":      return new Select(node, inputs, port);
67	            case "sigmoid":     return new Map(node, inputs, port, ScalarFunctions.sigmoid());
68	            case "squareddifference": return new Join(node, inputs, port, ScalarFunctions.squareddifference());
69	            case "sub":         return new Join(node, inputs, port, ScalarFunctions.subtract());
70	            case "subtract":    return new Join(node, inputs, port, ScalarFunctions.subtract());
71	
72	            // nn ops
73	            case "biasadd":     return new Join(node, inputs, port, ScalarFunctions.add());
74	            case "elu":         return new Map(node, inputs, port, ScalarFunctions.elu());
75	            case "relu":        return new Map(node, inputs, port, ScalarFunctions.relu());
76	            case "selu":        return new Map(node, inputs, port, ScalarFunctions.selu());
77	
78	            // state ops
79	            case "variable":    return new Variable(node, inputs, port);
80	            case "variablev2":  return new Variable(node, inputs, port);
81	
82	            // evaluation no-ops
83	            case "stopgradient":return new Identity(node, inputs, port);
84	            case "noop":        return new NoOp(node, inputs, port);
85	        }
86	        return new NoOp(node, inputs, port);
87	    }
88	
89	}
