70	    public Optional<TensorFunction> function() {
71	        if (function == null) {
72	            if (isConstant()) {
73	                ExpressionNode constant = new ReferenceNode(Reference.simple("constant", vespaName()));
74	                function = new TensorFunctionNode.TensorFunctionExpressionNode(constant);
75	            } else if (outputs.size() > 1) {
76	                macro = lazyGetFunction();
77	                function = new VariableTensor(macroName(), type.type());
78	            } else {
79	                function = lazyGetFunction();
80	            }
81	        }
82	        return Optional.ofNullable(function);
83	    }
