16	/**
17	 * A Vespa tensor type is ordered by the lexicographical ordering of dimension
18	 * names. TensorFlow tensors have an explicit ordering of their dimensions.
19	 * During import, we need to track the Vespa dimension that matches the
20	 * corresponding TensorFlow dimension as the ordering can change after
21	 * dimension renaming. That is the purpose of this class.
22	 *
23	 * @author lesters
24	 */
25	public class OrderedTensorType {
26	
27	    private final TensorType type;
28	    private final List<TensorType.Dimension> dimensions;
29	
30	    private final long[] innerSizesTensorFlow;
31	    private final long[] innerSizesVespa;
32	    private final int[] dimensionMap;
33	
34	    private OrderedTensorType(List<TensorType.Dimension> dimensions) {
35	        this.dimensions = Collections.unmodifiableList(dimensions);
36	        this.type = new TensorType.Builder(dimensions).build();
37	        this.innerSizesTensorFlow = new long[dimensions.size()];
38	        this.innerSizesVespa = new long[dimensions.size()];
39	        this.dimensionMap = createDimensionMap();
40	    }
41	
42	    public TensorType type() {
43	        return this.type;
44	    }
45	
46	    public int rank() { return dimensions.size(); }
47	
48	    public List<TensorType.Dimension> dimensions() {
49	        return dimensions;
50	    }
51	
52	    public List<String> dimensionNames() {
53	        return dimensions.stream().map(TensorType.Dimension::name).collect(Collectors.toList());
54	    }
55	
56	    private int[] createDimensionMap() {
57	        int numDimensions = dimensions.size();
58	        if (numDimensions == 0) {
59	            return null;
60	        }
61	        innerSizesTensorFlow[numDimensions - 1] = 1;
62	        innerSizesVespa[numDimensions - 1] = 1;
63	        for (int i = numDimensions - 1; --i >= 0; ) {
64	            innerSizesTensorFlow[i] = dimensions().get(i+1).size().orElse(-1L) * innerSizesTensorFlow[i+1];
65	            innerSizesVespa[i] = type.dimensions().get(i+1).size().orElse(-1L) * innerSizesVespa[i+1];
66	        }
67	        int[] mapping = new int[numDimensions];
68	        for (int i = 0; i < numDimensions; ++i) {
69	            TensorType.Dimension dim1 = dimensions().get(i);
70	            for (int j = 0; j < numDimensions; ++j) {
71	                TensorType.Dimension dim2 = type.dimensions().get(j);
72	                if (dim1.equals(dim2)) {
73	                    mapping[i] = j;
74	                    break;
75	                }
76	            }
77	        }
78	        return mapping;
79	    }
